      !! bin-interleaved second copy of pp_p/pp_r/pp_ra/pp_c, laid out so
      !! that lane iab's primitive k sits next to lane iab+1's.
      logical,  intent(in)    :: sD(nseg)
      integer,  intent(in)    :: sp_i(npair), sp_j(npair)
